css:
.mag-newsletter-widget {
  background-color: var(--bs-tertiary-bg, #1a1a1a);
  border: 1px solid var(--border-color, #333);
  padding: 2rem;
  border-radius: var(--radius, 12px);
  text-align: left;
  transition: transform 0.3s ease;
  margin-bottom: 2rem;
}
.mag-newsletter-widget h4 {
  color: var(--mag-title, #fff);
  font-family: var(--font-title, 'Playfair Display', serif);
  font-size: 1.5rem;
  margin-bottom: 1rem;
  font-weight: 700;
}
.mag-newsletter-widget p {
  color: rgba(255,255,255,0.6);
  font-size: 0.9rem;
  line-height: 1.5;
  margin-bottom: 1.5rem;
}
.mag-newsletter-widget .form-group { margin-bottom: 1rem; }
.mag-newsletter-widget input {
  width: 100%;
  padding: 12px 15px;
  border: none;
  border-radius: 6px;
  background: #fff;
  color: #333;
  font-size: 0.95rem;
  outline: none;
}
.mag-newsletter-widget input:focus {
  box-shadow: 0 0 0 2px var(--mag-primary, #0d6efd);
}
.mag-newsletter-widget button {
  width: 100%;
  padding: 12px;
  background-color: var(--mag-primary, #0d6efd);
  color: white;
  border: none;
  border-radius: 6px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  cursor: pointer;
  transition: opacity 0.2s;
}
.mag-newsletter-widget button:hover { opacity: 0.9; }
.nl-footer {
  margin-top: 1rem;
  font-size: 0.75rem;
  color: rgba(255,255,255,0.4);
}
#nl-status {
  margin-top: 10px;
  font-size: 0.85rem;
  font-weight: bold;
  display: none;
  padding: 10px;
  border-radius: 6px;
}

javascript:
document.getElementById('nl-form').addEventListener('submit', function(ev) {
  ev.preventDefault();
  const form = ev.target;
  const btn = document.getElementById('nl-btn');
  const status = document.getElementById('nl-status');
  const data = new FormData(form);

  const btnOriginalText = btn.innerHTML;
  btn.innerHTML = 'A enviar...';
  btn.style.opacity = '0.7';

  fetch(form.action, {
    method: form.method,
    body: data,
    headers: { 'Accept': 'application/json' }
  }).then(response => {
    if (response.ok) {
      status.innerHTML = '&#10003; Obrigado por assinar!';
      status.style.display = 'block';
      status.style.backgroundColor = 'rgba(40,167,69,0.1)';
      status.style.color = '#28a745';
      form.reset();
    } else {
      status.innerHTML = '&#9888; Erro ao enviar. Tente novamente.';
      status.style.display = 'block';
      status.style.backgroundColor = 'rgba(220,53,69,0.1)';
      status.style.color = '#dc3545';
    }
  }).catch(error => {
    status.innerHTML = '&#9888; Erro de conexao.';
    status.style.display = 'block';
    status.style.color = '#dc3545';
  }).finally(() => {
    btn.innerHTML = btnOriginalText;
    btn.style.opacity = '1';
  });
});
